// === Tab: mySketch ===
//-- let Harmonic Motion - 03 - Tesseracts - Transport
//-- Siddhartha, let 30th let 2019 -------
let dt = 0.0;
let driftTime = 30;
let fadetime = 100;
let c = 0;
let ndivs = 4;
let nt = ndivs*ndivs;
let step;
color [] cols = {"#403f4c", "#3f8efc", "#2667ff", "#f9dc5c"};
let counter = 0;
let indx1, indx2;
let trigger = false;

tesseract [] t;

function setup() {
  createCanvas(800, 800);
  step = width/ndivs;
  background("#bb342");

  t = new Array(nt);
  let count = 0;
  for (j=0; j<height; j+=step) {
    for (i=0; i<width; i+=step) {    
      //t[count] = new tesseract(int(random(3,8)), i+step/2, j+step/2, step*0.3);
      t[count] = new tesseract(3 + j/step, i+step/2, j+step/2, step*0.35, 5 + j/step);
      count++;
    }
  }
}

function draw() {
  noStroke();
  fill("#bb342");
  rect(0, 0, width, height);

  for (i=0; i<nt; ++i) {
    if (t[i].flag) {
      t[i].showOrMove(255, 100);
      t[i].nudgeOrMove( dt*1.0 );
    }
  }

  dt += 0.25;

  counter++;

  if ( (counter % fadetime == 0) && (trigger) ){
    t[indx1].xx = (t[indx1].xx+t[indx1].dx+width)%width;
    t[indx1].yy = (t[indx1].yy+t[indx1].dy+height)%height;
    t[indx2].xx = (t[indx2].xx-t[indx1].dx+width)%width;
    t[indx2].yy = (t[indx2].yy-t[indx1].dy+height)%height;
    trigger = false;
  }

  if ( (counter)%(driftTime+fadetime)==0 ) {
    for (i=0; i<nt; ++i) {
      t[i].which = 0;
      t[i].nudgeOrMove( dt*1.0 );
      t[i].dx = 0.0;
    }
  }
}

function mousePressed() {
  indx1 = int(random(nt));
  indx2 = int(random(nt));
  while (indx1==indx2) {
    indx2 = int(random(nt));
  }
  t[indx1].which = 1;
  t[indx2].which = 1;
  let dx = (t[indx2].xx - t[indx1].xx);
  let dy = (t[indx2].yy - t[indx1].yy);
  t[indx1].dx = dx;
  t[indx1].dy = dy;
  t[indx2].dx = -dx;
  t[indx2].dy = -dy;
  trigger = true;

  counter = 0;
}

// === Tab: tab2 ===
class tesseract{
  N;
  float [] xc;
  float [] yc;
  float [] xcOrig;
  float [] ycOrig;
  float [] phase;
  float [] rad2;
  rad;
  xx;
  yy;
  ntri;
  int [][] indxTri;
  color [] colarray;
  flag;
  dx;
  dy;
  which;

  constructor(n, x, y, r, ntri_) {
    N = n;
    xc = new Array(N);
    yc = new Array(N);
    xcOrig = new Array(N);
    ycOrig = new Array(N);
    phase = new float [N];
    rad2 = new float [N];
    rad = r;
    xx = x;
    yy = y;
    dx = 0.0;
    dy = 0.0;
    ntri = ntri_;
    indxTri = new Array(ntri)[3];
    colarray = new Array(ntri);
    flag = true;
    which = 0;

    for(i=0; i<N; ++i){
      xc[i] = xx + rad*cos(TWO_PI*i/N);
      yc[i] = yy + rad*sin(TWO_PI*i/N);
      phase[i] = random(TWO_PI);
      rad2[i] = random(4);
    }

    let i1, i2, i3;
    for(i=0; i<ntri; ++i){
      i1 = int(random(N));
      i2 = int(random(N));  
      i3 = int(random(N));    
      indxTri[i][0] = i1;
      indxTri[i][1] = i2;
      indxTri[i][2] = i3;
      colarray[i] = cols[int(random(cols.length))];
    }    

  }

  function nudge( dt_ ) {
    for(i=0; i<N; ++i){
      xc[i] = xx + rad*cos(TWO_PI*i/N + dt_*0.05) + rad2[i]*cos( dt_ + phase[i]);
      yc[i] = yy + rad*sin(TWO_PI*i/N + phase[i] + dt_*0.02) + rad2[i]*sin( dt_ + phase[i]);
    }
  }

  function nudgeOrMove( dt_ ) {
  	if (which == 0){
	    for(i=0; i<N; ++i){
	      xc[i] = xx + rad*cos(TWO_PI*i/N + dt_*0.05) + rad2[i]*cos( dt_ + phase[i]);
	      yc[i] = yy + rad*sin(TWO_PI*i/N + phase[i] + dt_*0.02) + rad2[i]*sin( dt_ + phase[i]);
	      xcOrig[i] = xc[i];
	      ycOrig[i] = yc[i];
  		}
  	} else {
      if( counter < fadetime ) {
        for(i=0; i<N; ++i){
          xc[i] = xx + rad*cos(TWO_PI*i/N + dt_*0.05) + rad2[i]*cos( dt_ + phase[i]);
          yc[i] = yy + rad*sin(TWO_PI*i/N + phase[i] + dt_*0.02) + rad2[i]*sin( dt_ + phase[i]);
          xcOrig[i] = xc[i];
          ycOrig[i] = yc[i];
        }
      } else {
    		for(i=0; i<N; ++i){
    			xc[i] = xcOrig[i] + dx*float( (counter-fadetime)%(driftTime) )/(driftTime);
    			yc[i] = ycOrig[i] + dy*float( (counter-fadetime)%(driftTime) )/(driftTime);
    			xc[i] = (xc[i]+ width)%width;
    			yc[i] = (yc[i]+ height)%height;
        }
		  }	
  	}
  }

  function show() {
    stroke("#d8c99b");
    strokeWeight(2);
    for(i=0; i<N; ++i){
      for(j=i; j<N; ++j){
        line(xc[i], yc[i], xc[j], yc[j]);
      }
    }
    fillTriangles(100);
  }

  function showOrMove(alphaLines, alphaTri) {
  	if(which==0){
	    for(i=0; i<N; ++i){
	      for(j=i; j<N; ++j){
          stroke("#d8c99b", alphaLines);
          strokeWeight(2);
	        line(xc[i], yc[i], xc[j], yc[j]);
          stroke("#d8c99b");
	        ellipse(xc[i], yc[i], 8, 8);
	      }
	    }
	    fillTriangles(alphaTri);
		} else {
        if(counter<fadetime){
          for(i=0; i<N; ++i){
            for(j=i; j<N; ++j){
              stroke("#d8c99b", alphaLines*(1.0 - float(counter)/fadetime));
              strokeWeight(2);
              line(xc[i], yc[i], xc[j], yc[j]);
              stroke("#d8c99b");
              ellipse(xc[i], yc[i], 8, 8);
            }
          }
          fillTriangles(alphaTri*(1.0 - float(counter)/fadetime));
        } else {
  		    noStroke();
      		fill("#d8c99b",255);
  		    // strokeWeight(2);
  	    	for(i=0; i<N; ++i){
  	    	  	ellipse(xc[i], yc[i], 8, 8);
  	    	}
        }
	    }
	}

  function fillTriangles(alpha) {
    noStroke();
    for(i=0; i<ntri; ++i){
      fill(colarray[i],alpha);
      triangle( xc[indxTri[i][0]], yc[indxTri[i][0]], xc[indxTri[i][1]], yc[indxTri[i][1]], xc[indxTri[i][2]], yc[indxTri[i][2]] );      
    }
  }

}

